-- Read-only data-safety release gate for migration 030.
-- Candidate 030 fields are read through to_jsonb() so this works before they exist.
with check_rows(check_name, row_count, is_blocking, passed, explanation) as (
  select 'staged orders', count(*), false, true, 'Informational total of current staged SPS source documents.' from public.sps_staged_orders
  union all select 'promoted staged orders', count(*) filter (where review_status = 'promoted' or promoted_order_id is not null), false, true, 'Grandfathered promoted evidence will not be rewritten.' from public.sps_staged_orders
  union all select 'staged orders without organization', count(*) filter (where organization_id is null), true, count(*) filter (where organization_id is null) = 0, 'Every staged document must remain organization-scoped.' from public.sps_staged_orders
  union all select 'staged orders without external PO', count(*) filter (where nullif(btrim(external_po), '') is null), true, count(*) filter (where nullif(btrim(external_po), '') is null) = 0, 'Existing source documents require a business PO reference.' from public.sps_staged_orders
  union all select 'current review status distribution', count(distinct review_status), false, true, 'Informational count of current review statuses.' from public.sps_staged_orders
  union all select 'current mapping status distribution', count(distinct mapping_status), false, true, 'Informational count of current mapping statuses.' from public.sps_staged_orders
  union all select 'duplicate current partner/PO keys', count(*), false, true, 'Informational: 030 deliberately permits separate source documents sharing a business PO.' from (select organization_id, source_system, trading_partner_id, external_po from public.sps_staged_orders where trading_partner_id is not null group by 1,2,3,4 having count(*) > 1) d
  union all select 'duplicate current global/PO keys', count(*), false, true, 'Informational: 030 deliberately permits separate source documents sharing a business PO.' from (select organization_id, source_system, external_po from public.sps_staged_orders where trading_partner_id is null group by 1,2,3 having count(*) > 1) d
  union all select 'candidate duplicate source document keys', count(*), true, count(*) = 0, 'A non-null durable source identity must be unique per organization and source system.' from (select organization_id, source_system, to_jsonb(s)->>'source_document_key' as source_document_key from public.sps_staged_orders s where nullif(to_jsonb(s)->>'source_document_key','') is not null group by 1,2,3 having count(*) > 1) d
  union all select 'legacy rows without durable source identity', count(*), false, true, 'Allowed grandfathered legacy/sandbox rows; 030 keeps this provenance nullable.' from public.sps_staged_orders s where nullif(to_jsonb(s)->>'source_document_key','') is null
  union all select 'promoted legacy rows without durable source identity', count(*), false, true, 'Allowed grandfathered evidence; it remains immutable and is not rewritten.' from public.sps_staged_orders s where (s.review_status = 'promoted' or s.promoted_order_id is not null) and nullif(to_jsonb(s)->>'source_document_key','') is null
  union all select 'orphan staged lines', count(*), true, count(*) = 0, 'Every staged line must have a same-organization staged source document.' from public.sps_staged_order_lines l left join public.sps_staged_orders s on s.id=l.staged_order_id and s.organization_id=l.organization_id where s.id is null
  union all select 'orphan staged exceptions', count(*), true, count(*) = 0, 'Every staged exception must have a same-organization staged source document.' from public.sps_order_exceptions e left join public.sps_staged_orders s on s.id=e.staged_order_id and s.organization_id=e.organization_id where s.id is null
  union all select 'orphan customer mapping targets', count(*), true, count(*) = 0, 'Native customer mapping targets must exist in the mapping organization.' from public.integration_customer_mappings m left join public.customers c on c.id=m.customer_id and c.organization_id=m.organization_id where m.customer_id is not null and c.id is null
  union all select 'inactive customer mapping targets', count(*), true, count(*) = 0, 'Native customer targets must be active for future promotion.' from public.integration_customer_mappings m join public.customers c on c.id=m.customer_id and c.organization_id=m.organization_id where m.customer_id is not null and c.status <> 'active'
  union all select 'orphan ship-to mapping targets', count(*), true, count(*) = 0, 'Native ship-to mapping targets must exist in the mapping organization.' from public.integration_ship_to_mappings m left join public.customer_ship_tos st on st.id=m.ship_to_id and st.organization_id=m.organization_id where m.ship_to_id is not null and st.id is null
  union all select 'inactive ship-to mapping targets', count(*), true, count(*) = 0, 'Native ship-to targets must be active for future promotion.' from public.integration_ship_to_mappings m join public.customer_ship_tos st on st.id=m.ship_to_id and st.organization_id=m.organization_id where m.ship_to_id is not null and st.status <> 'active'
  union all select 'orphan item mapping targets', count(*), true, count(*) = 0, 'Native item mapping targets must exist in the mapping organization.' from public.integration_item_mappings m left join public.items i on i.id=m.item_id and i.organization_id=m.organization_id where m.item_id is not null and i.id is null
  union all select 'inactive item mapping targets', count(*), true, count(*) = 0, 'Native item targets must be active for future promotion.' from public.integration_item_mappings m join public.items i on i.id=m.item_id and i.organization_id=m.organization_id where m.item_id is not null and i.status <> 'active'
  union all select 'invalid promoted-order references', count(*), true, count(*) = 0, 'Promoted staged evidence must point to a same-organization operational order.' from public.sps_staged_orders s left join public.orders o on o.id=s.promoted_order_id and o.organization_id=s.organization_id where s.promoted_order_id is not null and o.id is null
  union all select 'duplicate operational orders per staged source', count(*), true, count(*) = 0, 'At most one operational order may reference a staged source document.' from (select organization_id, sps_staged_order_id from public.orders where sps_staged_order_id is not null group by 1,2 having count(*) > 1) d
  union all select 'null line quantities', count(*), true, count(*) = 0, 'Future promotion requires a positive source quantity.' from public.sps_staged_order_lines where quantity is null
  union all select 'zero or negative line quantities', count(*), true, count(*) = 0, 'Future promotion requires a positive source quantity.' from public.sps_staged_order_lines where quantity <= 0
  union all select 'blank SPS UOM values', count(*), true, count(*) = 0, 'Future promotion requires an explicit SPS UOM.' from public.sps_staged_order_lines where nullif(btrim(sps_uom),'') is null
  union all select 'known UOM mismatches', count(*), true, count(*) = 0, '030 blocks future promotion until UOM is an exact match.' from public.sps_staged_order_lines where uom_status = 'mismatch'
  union all select 'ambiguous staged item mappings', count(*), true, count(*) = 0, 'Ambiguous item reconciliation must remain under review.' from public.sps_staged_order_lines where item_mapping_status = 'ambiguous'
  union all select 'existing 850/860 document types', count(*) filter (where (to_jsonb(s)->>'document_type') in ('850','860')), false, true, 'Informational existing typed documents; 850 and 860 may share a PO.' from public.sps_staged_orders s
  union all select 'same-PO typed document patterns', count(*), false, true, 'Informational potential revision families; 030 does not collapse them.' from (select organization_id, source_system, coalesce(to_jsonb(s)->>'business_po_number',s.external_po) as po from public.sps_staged_orders s group by 1,2,3 having count(*) > 1) d
  union all select 'promoted records that would fail future line rules', count(*), false, true, 'Grandfathered promoted history is preserved rather than rewritten.' from public.sps_staged_orders s where (s.review_status='promoted' or s.promoted_order_id is not null) and exists (select 1 from public.sps_staged_order_lines l where l.staged_order_id=s.id and (l.quantity is null or l.quantity <= 0 or nullif(btrim(l.sps_uom),'') is null or l.uom_status <> 'match'))
), results as (
  select check_name, row_count, case when is_blocking then 'BLOCKING' else 'NON_BLOCKING' end as classification, case when passed then 'PASS' else 'FAIL' end as result, explanation from check_rows
  union all
  select 'FINAL RELEASE DECISION', null, 'BLOCKING', case when bool_and(passed or not is_blocking) then 'SAFE TO APPLY 030' else 'BLOCKERS FOUND' end, 'Apply only when every blocking data-safety check passes.' from check_rows
)
select * from results
order by case when check_name = 'FINAL RELEASE DECISION' then 1 else 0 end, check_name;
